import React, { useState } from 'react';
import './CartItemWithOptions.css';

const CartItemWithOptions = ({ item, onUpdate, onRemove }) => {
  const [showOptions, setShowOptions] = useState(false);
  const [selectedOptions, setSelectedOptions] = useState(item.options || {
    size: 'M',
    spice: 'mild',
    toppings: []
  });

  const options = {
    size: [
      { id: 'M', name: 'Regular', price: 0 },
      { id: 'L', name: 'Large', price: 3.00 }
    ],
    spice: [
      { id: 'mild', name: '보통', price: 0 },
      { id: 'hot', name: '매움', price: 0 },
      { id: 'very-hot', name: '아주매움', price: 0 }
    ],
    toppings: [
      { id: 'cheese', name: 'Extra Cheese', price: 2.00 },
      { id: 'egg', name: 'Fried Egg', price: 1.50 }
    ]
  };

  const handleOptionChange = (category, value) => {
    const newOptions = { ...selectedOptions, [category]: value };
    setSelectedOptions(newOptions);
    onUpdate(item.id, { options: newOptions });
  };

  const handleToppingToggle = (toppingId) => {
    const newToppings = selectedOptions.toppings.includes(toppingId)
      ? selectedOptions.toppings.filter(id => id !== toppingId)
      : [...selectedOptions.toppings, toppingId];

    const newOptions = { ...selectedOptions, toppings: newToppings };
    setSelectedOptions(newOptions);
    onUpdate(item.id, { options: newOptions });
  };

  const getOptionsText = () => {
    const optionsText = [];

    if (selectedOptions.size && selectedOptions.size !== 'M') {
      optionsText.push(`Size: ${options.size.find(s => s.id === selectedOptions.size)?.name}`);
    }

    if (selectedOptions.spice && selectedOptions.spice !== 'mild') {
      optionsText.push(`맵기: ${options.spice.find(s => s.id === selectedOptions.spice)?.name}`);
    }

    if (selectedOptions.toppings && selectedOptions.toppings.length > 0) {
      const toppingNames = selectedOptions.toppings.map(id => 
        options.toppings.find(t => t.id === id)?.name
      ).join(', ');
      optionsText.push(`토핑: ${toppingNames}`);
    }

    return optionsText.length > 0 ? optionsText.join(' | ') : '기본 옵션';
  };

  const calculateExtraPrice = () => {
    let extra = 0;

    // Size 추가 가격
    if (selectedOptions.size) {
      const sizeOption = options.size.find(s => s.id === selectedOptions.size);
      if (sizeOption) extra += sizeOption.price;
    }

    // Toppings 추가 가격
    if (selectedOptions.toppings) {
      selectedOptions.toppings.forEach(toppingId => {
        const topping = options.toppings.find(t => t.id === toppingId);
        if (topping) extra += topping.price;
      });
    }

    return extra;
  };

  const totalPrice = (item.price + calculateExtraPrice()) * item.quantity;

  return (
    <div className="cart-item-with-options">
      <div className="cart-item-main">
        <div className="cart-item-info">
          <span className="cart-item-name">{item.name}</span>
          <span className="cart-item-options">{getOptionsText()}</span>
          <span className="cart-item-qty">x{item.quantity}</span>
        </div>
        <div className="cart-item-actions">
          <span className="cart-item-price">RM {totalPrice.toFixed(2)}</span>
          <button 
            className="options-btn"
            onClick={() => setShowOptions(!showOptions)}
          >
            Options
          </button>
          <button 
            className="remove-btn"
            onClick={() => onRemove(item.id)}
          >
            ×
          </button>
        </div>
      </div>

      {showOptions && (
        <div className="options-panel">
          <div className="option-group">
            <span className="option-label">Size:</span>
            <div className="option-buttons">
              {options.size.map(size => (
                <button
                  key={size.id}
                  className={`option-btn ${selectedOptions.size === size.id ? 'selected' : ''}`}
                  onClick={() => handleOptionChange('size', size.id)}
                >
                  {size.name}
                  {size.price > 0 && ` (+RM ${size.price.toFixed(2)})`}
                </button>
              ))}
            </div>
          </div>

          <div className="option-group">
            <span className="option-label">맵기:</span>
            <div className="option-buttons">
              {options.spice.map(spice => (
                <button
                  key={spice.id}
                  className={`option-btn ${selectedOptions.spice === spice.id ? 'selected' : ''}`}
                  onClick={() => handleOptionChange('spice', spice.id)}
                >
                  {spice.name}
                </button>
              ))}
            </div>
          </div>

          <div className="option-group">
            <span className="option-label">토핑:</span>
            <div className="option-checkboxes">
              {options.toppings.map(topping => (
                <label key={topping.id} className="checkbox-label">
                  <input
                    type="checkbox"
                    checked={selectedOptions.toppings?.includes(topping.id) || false}
                    onChange={() => handleToppingToggle(topping.id)}
                  />
                  <span>{topping.name} (+RM {topping.price.toFixed(2)})</span>
                </label>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CartItemWithOptions;
